[
  {
    "server_name": "serena",
    "tools": [
      {
        "name": "replace_content",
        "title": "Replace Content",
        "description": "Replaces one or more occurrences of a given pattern in a file with new content.\n\nVERY IMPORTANT: The \"regex\" mode allows very large sections of code to be replaced WITHOUT\nquoting them fully: use a needle of the form \"beginning.*?end-of-text-to-be-replaced\" with\nwildcards instead of pasting the exact original text — shorter, cheaper, and you cannot make\nmistakes, because an ambiguous match returns an error you can refine, so wildcards are safe.\nPrefer regex mode with suitable wildcards for long multi-line replacements; use the\nsymbol-level editors when replacing a whole method/class.",
        "inputSchema": {
          "properties": {
            "relative_path": {
              "title": "Relative Path",
              "type": "string",
              "description": "The relative path to the file."
            },
            "needle": {
              "title": "Needle",
              "type": "string",
              "description": "The string or regex pattern to search for.\nIf `mode` is \"literal\", this string will be matched exactly.\nIf `mode` is \"regex\", this string will be treated as a regular expression (syntax of Python's `re` module,\nwith flags DOTALL and MULTILINE enabled)."
            },
            "repl": {
              "title": "Repl",
              "type": "string",
              "description": "The replacement string (verbatim).\nIf mode is \"regex\", the string can contain backreferences to matched groups in the needle regex,\nspecified using the syntax $!1, $!2, etc. for groups 1, 2, etc."
            },
            "mode": {
              "enum": [
                "literal",
                "regex"
              ],
              "title": "Mode",
              "type": "string",
              "description": "Either \"literal\" or \"regex\", specifying how the `needle` parameter is to be interpreted."
            },
            "allow_multiple_occurrences": {
              "default": false,
              "title": "Allow Multiple Occurrences",
              "type": "boolean",
              "description": "Whether to allow matching and replacing multiple occurrences.\nIf false and multiple occurrences are found, an error will be returned."
            }
          },
          "required": [
            "relative_path",
            "needle",
            "repl",
            "mode"
          ],
          "title": "applyArguments",
          "type": "object"
        },
        "annotations": {
          "title": "Replace Content",
          "readOnlyHint": false,
          "destructiveHint": true
        }
      },
      {
        "name": "replace_in_files",
        "title": "Replace In Files",
        "description": "Replaces occurrences of a pattern across multiple files in ONE call.\n\nThis is the preferred tool for repeated small edits (renames, import swaps, annotation changes,\npath prefixes) spanning several files or many places in one file: one call with a SHORT pattern\nreplaces many single-file replacements with long disambiguating needles.\n\nRecommended protocol whenever there is ANY risk of unintended replacements:\n1. Call with dry_run=True: every prospective change is returned as a minimal line diff with an\n   occurrence id; nothing is modified.\n2. Call again with dry_run=False, passing the ids you want in occurrence_ids (omit it to apply\n   all). You pick the desired replacements from the list - no counting, no needle-crafting.\n\nFor clearly unambiguous bulk replacements you may skip the dry run; pass expected_count as a\nguard. If the actual number of matches differs, NOTHING is changed and the diff list is\nreturned, so a failed guard costs one call and gives you the dry-run output to select from. Returns in a dry run, the prospective changes; otherwise a summary of the applied replacements.",
        "inputSchema": {
          "properties": {
            "needle": {
              "title": "Needle",
              "type": "string",
              "description": "The string (mode \"literal\") or regular expression (mode \"regex\"; Python `re`\nsyntax with DOTALL and MULTILINE) to search for."
            },
            "repl": {
              "title": "Repl",
              "type": "string",
              "description": "The replacement string. In regex mode, backreferences to matched groups can be\nspecified as $!1, $!2, etc."
            },
            "mode": {
              "enum": [
                "literal",
                "regex"
              ],
              "title": "Mode",
              "type": "string",
              "description": "Either \"literal\" or \"regex\", specifying how `needle` is to be interpreted."
            },
            "relative_path": {
              "default": "",
              "title": "Relative Path",
              "type": "string",
              "description": "Only consider this file or directory (default: the whole project)."
            },
            "paths_include_glob": {
              "default": "",
              "title": "Paths Include Glob",
              "type": "string",
              "description": "Optional glob (relative to the project root, e.g. \"src/**/*.java\")\nrestricting which files are considered."
            },
            "paths_exclude_glob": {
              "default": "",
              "title": "Paths Exclude Glob",
              "type": "string",
              "description": "Optional glob of files to exclude; takes precedence over the include glob."
            },
            "dry_run": {
              "default": false,
              "title": "Dry Run",
              "type": "boolean",
              "description": "If True, do not modify anything; return the prospective changes as a list of\ndiffs with occurrence ids."
            },
            "occurrence_ids": {
              "anyOf": [
                {
                  "items": {
                    "type": "string"
                  },
                  "type": "array"
                },
                {
                  "type": "null"
                }
              ],
              "default": null,
              "title": "Occurrence Ids",
              "description": "Optional list of occurrence ids (obtained from a dry run) to which the\nreplacement is restricted; if any id is unknown or stale, NOTHING is changed. If omitted,\nall occurrences are replaced."
            },
            "expected_count": {
              "default": -1,
              "title": "Expected Count",
              "type": "integer",
              "description": "Optional guard for calls without occurrence_ids: the number of\noccurrences you expect to be replaced. If the actual count differs, nothing is changed and\nthe list of prospective changes is returned. -1 disables the guard."
            },
            "max_answer_chars": {
              "default": -1,
              "title": "Max Answer Chars",
              "type": "integer",
              "description": "If the output exceeds this many characters, a shortened version is\nreturned. -1 uses the configured default."
            }
          },
          "required": [
            "needle",
            "repl",
            "mode"
          ],
          "title": "applyArguments",
          "type": "object"
        },
        "annotations": {
          "title": "Replace In Files",
          "readOnlyHint": false,
          "destructiveHint": true
        }
      },
      {
        "name": "replace_symbol_body",
        "title": "Replace Symbol Body",
        "description": "Replaces the body of the given symbol.\n\nIMPORTANT: Only replace symbol bodies if you have previously made a retrieval with include_body=True and thus know what\nconstitutes the body!.",
        "inputSchema": {
          "properties": {
            "name_path": {
              "title": "Name Path",
              "type": "string",
              "description": "Name path of the symbol whose body to replace."
            },
            "relative_path": {
              "title": "Relative Path",
              "type": "string",
              "description": "The relative path to the file containing the symbol."
            },
            "body": {
              "title": "Body",
              "type": "string",
              "description": "The new symbol body. The symbol body is the definition of a symbol\nin the programming language, including e.g. the signature line for functions.\nDepending on the language, it may or may not include a preceding docstring or other preceding annotations."
            }
          },
          "required": [
            "name_path",
            "relative_path",
            "body"
          ],
          "title": "applyArguments",
          "type": "object"
        },
        "annotations": {
          "title": "Replace Symbol Body",
          "readOnlyHint": false,
          "destructiveHint": true
        }
      },
      {
        "name": "insert_after_symbol",
        "title": "Insert After Symbol",
        "description": "Use this to insert code after a class/method/function definition.\nDon't use to insert after assignments (constants, fields).",
        "inputSchema": {
          "properties": {
            "name_path": {
              "title": "Name Path",
              "type": "string",
              "description": "Name path of the symbol after which to insert content."
            },
            "relative_path": {
              "title": "Relative Path",
              "type": "string",
              "description": "The relative path to the file containing the symbol."
            },
            "body": {
              "title": "Body",
              "type": "string",
              "description": "The body/content to be inserted. The inserted code shall begin with the next line after\nthe symbol."
            }
          },
